796	  async chatCompletion(
797	    request: ChatCompletionRequest,
798	  ): Promise<AsyncIterable<ChatCompletionChunk> | ChatCompletion> {
799	    const timeReceived = Date.now();
800	    // 0. Check model loaded and preprocess inputs
801	    const [selectedModelId, selectedPipeline, selectedChatConfig] =
802	      this.getLLMStates("ChatCompletionRequest", request.model);
803	    const selectedModelType =
804	      this.loadedModelIdToModelType.get(selectedModelId);
805	    API.postInitAndCheckFieldsChatCompletion(
806	      request,
807	      selectedModelId,
808	      selectedModelType!,
809	    );
810	    const genConfig: GenerationConfig = {
811	      frequency_penalty: request.frequency_penalty,
812	      presence_penalty: request.presence_penalty,
813	      repetition_penalty: request.repetition_penalty,
814	      max_tokens: request.max_tokens,
815	      stop: request.stop,
816	      top_p: request.top_p,
817	      temperature: request.temperature,
818	      logit_bias: request.logit_bias,
819	      logprobs: request.logprobs,
820	      top_logprobs: request.top_logprobs,
821	      response_format: request.response_format,
822	      ignore_eos: request.ignore_eos,
823	      enable_thinking: request.extra_body?.enable_thinking,
824	      enable_latency_breakdown: request.extra_body?.enable_latency_breakdown,
825	    };
826	
827	    // 0.5 Block wait until this pipeline finishes all previous requests
828	    const lock = this.loadedModelIdToLock.get(selectedModelId)!;
829	    await lock.acquire();
830	
831	    // 1. If request is streaming, return an AsyncIterable (an iterable version of `_generate()`)
832	    if (request.stream) {
833	      return this.asyncGenerate(
834	        request,
835	        selectedModelId,
836	        selectedPipeline,
837	        selectedChatConfig,
838	        genConfig,
839	        timeReceived,
840	      );
841	    }
842	
843	    // Big try-finally to release lock in case of errors
844	    try {
845	      if (request.seed !== null && request.seed !== undefined) {
846	        selectedPipeline.setSeed(request.seed);
847	      }
848	
849	      // 2. If request is non-streaming, directly reuse `_generate()`
850	      const n = request.n ? request.n : 1;
851	      const choices: Array<ChatCompletion.Choice> = [];
852	      let completion_tokens = 0;
853	      let prompt_tokens = 0;
854	      let prefill_time = 0;
855	      let decode_time = 0;
856	      let grammar_init_s = 0;
857	      let grammar_per_token_s = 0;
858	      for (let i = 0; i < n; i++) {
859	        let outputMessage: string;
860	        if (this.interruptSignal) {
861	          // A single interrupt signal should stop all choices' generations
862	          selectedPipeline.triggerStop();
863	          outputMessage = "";
864	        } else {
865	          outputMessage = await this._generate(
866	            request,
867	            selectedPipeline,
868	            selectedChatConfig,
869	            genConfig,
870	          );
871	        }
872	        let finish_reason = selectedPipeline.getFinishReason()!;
873	
874	        // 3. Post processing for function calling
875	        const isFunctionCalling =
876	          request.tools !== undefined && request.tools !== null;
877	        let tool_calls: Array<ChatCompletionMessageToolCall> | undefined;
878	        if (
879	          selectedPipeline.getFinishReason() === "stop" &&
880	          isFunctionCalling
881	        ) {
882	          // If stopped due to length or abort, cannot output return tool_calls field
883	          finish_reason = "tool_calls";
884	          tool_calls = getToolCallFromOutputMessage(
885	            outputMessage,
886	            /*isStreaming=*/ false,
887	          );
888	        }
889	
890	        choices.push({
891	          finish_reason: finish_reason,
892	          index: i,
893	          logprobs: request.logprobs
894	            ? ({
895	                content: selectedPipeline.getTokenLogprobArray(),
896	              } as ChatCompletion.Choice.Logprobs)
897	            : null,
898	          message: isFunctionCalling
899	            ? {
900	                content: null,
901	                tool_calls: tool_calls,
902	                role: "assistant",
903	              }
904	            : {
905	                content: outputMessage,
906	                role: "assistant",
907	              },
908	        });
909	        completion_tokens += selectedPipeline.getCurRoundDecodingTotalTokens();
910	        prompt_tokens += selectedPipeline.getCurRoundPrefillTotalTokens();
911	        prefill_time += selectedPipeline.getCurRoundPrefillTotalTime();
912	        decode_time += selectedPipeline.getCurRoundDecodingTotalTime();
913	        grammar_init_s += selectedPipeline.getCurRoundGrammarInitTotalTime();
914	        grammar_per_token_s +=
915	          selectedPipeline.getCurRoundGrammarPerTokenTotalTime();
916	      }
917	      const usedGrammar =
918	        "response_format" in request &&
919	        (request.response_format?.type === "grammar" ||
920	          request.response_format?.type === "json_object");
921	
922	      const latencyBreakdown: LatencyBreakdown =
923	        selectedPipeline.getCurRoundLatencyBreakdown();
924	
925	      const defaultExtra = {
926	        e2e_latency_s: (Date.now() - timeReceived) / 1000,
927	        prefill_tokens_per_s: prompt_tokens / prefill_time,
928	        decode_tokens_per_s: completion_tokens / decode_time,
929	        time_to_first_token_s: prefill_time,
930	        time_per_output_token_s: decode_time / completion_tokens,
931	        latencyBreakdown: request.extra_body?.enable_latency_breakdown
932	          ? latencyBreakdown
933	          : undefined,
934	      };
935	      const response: ChatCompletion = {
936	        id: crypto.randomUUID(),
937	        choices: choices,
938	        model: selectedModelId,
939	        object: "chat.completion",
940	        created: getUnixTimestampSeconds(),
941	        usage: {
942	          completion_tokens: completion_tokens,
943	          prompt_tokens: prompt_tokens,
944	          total_tokens: completion_tokens + prompt_tokens,
945	          extra: usedGrammar
946	            ? {
947	                ...defaultExtra,
948	                ...{
949	                  grammar_init_s: grammar_init_s,
950	                  grammar_per_token_s: grammar_per_token_s / completion_tokens,
951	                },
952	              }
953	            : defaultExtra,
954	        } as CompletionUsage,
955	      };
956	
957	      // Reset seed -- we do not want this seed to affect future requests
958	      if (request.seed !== null && request.seed !== undefined) {
959	        selectedPipeline.setSeed(Date.now());
960	      }
961	      return response;
962	    } finally {
963	      await lock.release();
964	    }
965	  }
