1156	  async getMaxStorageBufferBindingSize(): Promise<number> {
1157	    // First detect GPU
1158	    const gpuDetectOutput = await tvmjs.detectGPUDevice();
1159	    if (gpuDetectOutput == undefined) {
1160	      throw new WebGPUNotAvailableError();
1161	    }
1162	
1163	    const computeMB = (value: number) => {
1164	      return Math.ceil(value / (1 << 20)) + "MB";
1165	    };
1166	    const maxStorageBufferBindingSize =
1167	      gpuDetectOutput.device.limits.maxStorageBufferBindingSize;
1168	    const defaultMaxStorageBufferBindingSize = 1 << 30; // 1GB
1169	    if (maxStorageBufferBindingSize < defaultMaxStorageBufferBindingSize) {
1170	      log.warn(
1171	        `WARNING: the current maxStorageBufferBindingSize ` +
1172	          `(${computeMB(maxStorageBufferBindingSize)}) ` +
1173	          `may only work for a limited number of models, e.g.: \n` +
1174	          `- Llama-3.1-8B-Instruct-q4f16_1-MLC-1k \n` +
1175	          `- Llama-2-7b-chat-hf-q4f16_1-MLC-1k \n` +
1176	          `- RedPajama-INCITE-Chat-3B-v1-q4f16_1-MLC-1k \n` +
1177	          `- RedPajama-INCITE-Chat-3B-v1-q4f32_1-MLC-1k \n` +
1178	          `- TinyLlama-1.1B-Chat-v0.4-q4f16_1-MLC-1k \n` +
1179	          `- TinyLlama-1.1B-Chat-v0.4-q4f32_1-MLC-1k`,
1180	      );
1181	    }
1182	    return maxStorageBufferBindingSize;
1183	  }
