1221	  /**
1222	   * Return the model, its LLMChatPipeline, and ChatConfig to use. Throws error when unclear which
1223	   * model to load. Ensure all loadedModelIdToXXX maps contain entry for the selected modelId.
1224	   * @param requestName The type of request or API to load the model for. Needed for error throwing.
1225	   * @param modelType The typ of model, determining what type of pipeline to expect.
1226	   * @param modelId Model the user specified to load via the request. Required when multiple
1227	   *   models are loaded
1228	   */
1229	  private getModelStates(
1230	    requestName: string,
1231	    modelType: ModelType,
1232	    modelId?: string | null,
1233	  ): [string, LLMChatPipeline | EmbeddingPipeline, ChatConfig] {
1234	    // 0. Select model based on request.model and loadedModelIds
1235	    const loadedModelIds: string[] = Array.from(
1236	      this.loadedModelIdToPipeline.keys(),
1237	    );
1238	    const selectedModelId: string = getModelIdToUse(
1239	      loadedModelIds,
1240	      modelId,
1241	      requestName,
1242	    );
1243	
1244	    // 1. Retrieve pipeline
1245	    const selectedPipeline = this.loadedModelIdToPipeline.get(selectedModelId);
1246	    if (modelType === ModelType.LLM) {
1247	      if (!(selectedPipeline instanceof LLMChatPipeline)) {
1248	        throw new IncorrectPipelineLoadedError(
1249	          selectedModelId,
1250	          "LLMChatPipeline",
1251	          requestName,
1252	        );
1253	      }
1254	    } else {
1255	      // ModelType.Embedding
1256	      if (!(selectedPipeline instanceof EmbeddingPipeline)) {
1257	        throw new IncorrectPipelineLoadedError(
1258	          selectedModelId,
1259	          "EmbeddingPipeline",
1260	          requestName,
1261	        );
1262	      }
1263	      if (
1264	        findModelRecord(selectedModelId, this.appConfig).model_type !==
1265	        ModelType.embedding
1266	      ) {
1267	        throw new EmbeddingUnsupportedModelError(selectedModelId);
1268	      }
1269	    }
1270	
1271	    // 2. Retrieve chat config
1272	    const selectedChatConfig =
1273	      this.loadedModelIdToChatConfig.get(selectedModelId);
1274	    if (selectedChatConfig === undefined) {
1275	      throw new Error(
1276	        `InternalError: chat config not registered for ${selectedModelId}.`,
1277	      );
1278	    }
1279	
1280	    // 3. Make sure lock is initialized
1281	    if (!this.loadedModelIdToLock.has(selectedModelId)) {
1282	      throw new Error(
1283	        `InternalError: loadedModelIdToLock does not contain ${selectedModelId}`,
1284	      );
1285	    }
1286	    return [selectedModelId, selectedPipeline, selectedChatConfig];
1287	  }
